"""Read-only thread hierarchy endpoints.

Threads are projections over existing sessions. Parentage comes from
``thread_delegations``. Every endpoint performs the same session-ownership
check as the existing session APIs before returning data.
"""

import logging
from collections.abc import Callable
from typing import Any, TypeVar

from fastapi import APIRouter, HTTPException, Request

from yinshi.api.deps import (
    check_session_owner,
    get_db_for_request,
    get_tenant,
    get_user_email,
)
from yinshi.config import get_settings
from yinshi.models import (
    ThreadLimitsOut,
    ThreadOut,
    ThreadResultOut,
    ThreadTreeOut,
)
from yinshi.services.thread_queries import (
    ThreadNotFoundError,
    get_thread,
    get_thread_limits,
    get_thread_result,
    get_tree,
    list_children,
)

logger = logging.getLogger(__name__)
router = APIRouter(tags=["threads"])

_QueryResult = TypeVar("_QueryResult")


def _resolve_authorized_thread(
    db: Any,
    session_id: str,
    request: Request,
) -> None:
    """Fail with 404 when the session is missing or not owned."""
    session = db.execute("SELECT id FROM sessions WHERE id = ?", (session_id,)).fetchone()
    if session is None:
        raise HTTPException(status_code=404, detail="Session not found")
    check_session_owner(db, session_id, request)


def _hierarchy_enabled() -> bool:
    """Return whether the thread hierarchy feature flag is enabled."""
    return get_settings().thread_hierarchy_enabled


def _legacy_owner_email(request: Request) -> str | None:
    """Return the legacy per-repo owner filter for this request, when any."""
    if get_tenant(request) is not None:
        return None
    return get_user_email(request)


def _run_visible_query(operation: Callable[[], _QueryResult]) -> _QueryResult:
    """Map hidden ancestry to the standard not-found response."""
    try:
        return operation()
    except ThreadNotFoundError as exc:
        raise HTTPException(status_code=404, detail="Session not found") from exc


@router.get("/api/threads/{session_id}", response_model=ThreadOut)
def get_thread_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return one thread projection."""
    if not _hierarchy_enabled():
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return _run_visible_query(
            lambda: get_thread(db, session_id, owner_email=_legacy_owner_email(request))
        )


@router.get(
    "/api/threads/{session_id}/children",
    response_model=list[ThreadOut],
)
def get_thread_children_route(session_id: str, request: Request) -> list[dict[str, Any]]:
    """Return the direct children of a thread."""
    if not _hierarchy_enabled():
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return _run_visible_query(
            lambda: list_children(db, session_id, owner_email=_legacy_owner_email(request))
        )


@router.get("/api/threads/{session_id}/limits", response_model=ThreadLimitsOut)
def get_thread_limits_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return thread limits plus current usage and remaining allowances."""
    if not _hierarchy_enabled():
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return _run_visible_query(
            lambda: get_thread_limits(db, session_id, owner_email=_legacy_owner_email(request))
        )


@router.get("/api/threads/{session_id}/result", response_model=ThreadResultOut)
def get_thread_result_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return the sealed stored result for a delegated child thread."""
    if not _hierarchy_enabled():
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        owner_email = _legacy_owner_email(request)
        result = _run_visible_query(
            lambda: get_thread_result(db, session_id, owner_email=owner_email)
        )
    if result is None:
        raise HTTPException(status_code=404, detail="Thread result not found")
    return result


@router.get("/api/threads/{session_id}/tree", response_model=ThreadTreeOut)
def get_thread_tree_route(session_id: str, request: Request) -> dict[str, Any]:
    """Return the bounded root thread tree containing a session."""
    if not _hierarchy_enabled():
        raise HTTPException(status_code=404, detail="Thread hierarchy is disabled")
    with get_db_for_request(request) as db:
        _resolve_authorized_thread(db, session_id, request)
        return _run_visible_query(
            lambda: get_tree(db, session_id, owner_email=_legacy_owner_email(request))
        )

"""Endpoints for workspace (worktree) management."""

import logging
import sqlite3
from typing import Any

from fastapi import APIRouter, HTTPException, Request

from yinshi.api.deps import (
    check_owner,
    check_workspace_owner,
    get_db_for_request,
    get_tenant,
    get_user_email,
)
from yinshi.config import get_settings
from yinshi.exceptions import (
    GitError,
    RepoNotFoundError,
    WorkspaceHasDelegatedThreads,
    WorkspaceNotFoundError,
)
from yinshi.models import WorkspaceCreate, WorkspaceOut, WorkspaceUpdate
from yinshi.services.run_coordinator import get_run_coordinator
from yinshi.services.sidecar import release_sessions
from yinshi.services.workspace import create_workspace_for_repo, delete_workspace

logger = logging.getLogger(__name__)
router = APIRouter(tags=["workspaces"])

_UPDATABLE_COLUMNS = {"state"}
_RUNTIME_BUSY_DETAIL = "Workspace is still stopping; deletion can be retried"


def _reject_delegated_parent_workspace(
    db: sqlite3.Connection,
    workspace_id: str,
) -> None:
    """Refuse deletion before any teardown when sessions parent children."""
    delegation_row = db.execute(
        """SELECT count(*) AS child_count
           FROM thread_delegations d
           JOIN sessions s ON s.id = d.parent_session_id
           WHERE s.workspace_id = ?""",
        (workspace_id,),
    ).fetchone()
    assert delegation_row is not None
    if int(delegation_row["child_count"]) > 0:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "thread_children_present",
                "message": "Workspace sessions parent delegated child threads",
            },
        )


def _check_repo_owner(
    db: sqlite3.Connection,
    repo_id: str,
    request: Request,
) -> None:
    """In legacy mode, verify the authenticated user owns the repo."""
    if get_tenant(request):
        return
    repo = db.execute("SELECT owner_email FROM repos WHERE id = ?", (repo_id,)).fetchone()
    if repo:
        check_owner(repo["owner_email"], get_user_email(request))
    else:
        raise HTTPException(status_code=404, detail="Repo not found")


@router.get("/api/repos/{repo_id}/workspaces", response_model=list[WorkspaceOut])
def list_workspaces(repo_id: str, request: Request) -> list[dict[str, Any]]:
    """List all workspaces for a repo."""
    with get_db_for_request(request) as db:
        _check_repo_owner(db, repo_id, request)
        rows = db.execute(
            "SELECT * FROM workspaces WHERE repo_id = ? ORDER BY created_at DESC",
            (repo_id,),
        ).fetchall()
        return [dict(r) for r in rows]


@router.post(
    "/api/repos/{repo_id}/workspaces",
    response_model=WorkspaceOut,
    status_code=201,
)
async def create_workspace(
    repo_id: str,
    body: WorkspaceCreate,
    request: Request,
) -> dict[str, Any]:
    """Create a new worktree workspace."""
    email = get_user_email(request)
    username = email.split("@")[0] if email else None
    tenant = get_tenant(request)

    with get_db_for_request(request) as db:
        _check_repo_owner(db, repo_id, request)
        try:
            return await create_workspace_for_repo(
                db,
                repo_id,
                body.name,
                username=username,
                tenant=tenant,
            )
        except RepoNotFoundError:
            raise HTTPException(status_code=404, detail="Repo not found")
        except GitError as exc:
            raise HTTPException(status_code=409, detail=str(exc))


@router.patch("/api/workspaces/{workspace_id}", response_model=WorkspaceOut)
def update_workspace(
    workspace_id: str,
    body: WorkspaceUpdate,
    request: Request,
) -> dict[str, Any]:
    """Update workspace fields (currently only state)."""
    with get_db_for_request(request) as db:
        row = db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Workspace not found")
        check_workspace_owner(db, workspace_id, request)

        updates = {
            k: v for k, v in body.model_dump(exclude_unset=True).items() if k in _UPDATABLE_COLUMNS
        }
        if updates:
            sets = ", ".join(f"{k} = ?" for k in updates)
            vals = list(updates.values()) + [workspace_id]
            db.execute(f"UPDATE workspaces SET {sets} WHERE id = ?", vals)  # noqa: S608
            db.commit()
        updated = db.execute("SELECT * FROM workspaces WHERE id = ?", (workspace_id,)).fetchone()
        return dict(updated)


@router.delete("/api/workspaces/{workspace_id}", status_code=204)
async def remove_workspace(workspace_id: str, request: Request) -> None:
    """Stop runtime activity, then delete a workspace and its durable paths."""
    tenant = get_tenant(request)
    with get_db_for_request(request) as db:
        check_workspace_owner(db, workspace_id, request)
        _reject_delegated_parent_workspace(db, workspace_id)
        session_rows = db.execute(
            "SELECT id FROM sessions WHERE workspace_id = ?",
            (workspace_id,),
        ).fetchall()
        try:
            coordinator = get_run_coordinator()
            for session_row in session_rows:
                await coordinator.request_cancel(str(session_row["id"]))
            if request.app.state.mode == "desktop":
                # Desktop shares one long-lived sidecar, so these pi sessions
                # would otherwise stay resident until the app quits. Hosted
                # mode destroys the whole container below instead.
                await release_sessions(
                    get_settings().sidecar_socket_path,
                    [str(session_row["id"]) for session_row in session_rows],
                )
            elif tenant is not None:
                container_manager = getattr(request.app.state, "container_manager", None)
                if container_manager is not None:
                    container_removed = await container_manager.destroy_container(
                        tenant.user_id,
                        runtime_id=workspace_id,
                    )
                    if not container_removed:
                        raise HTTPException(status_code=409, detail=_RUNTIME_BUSY_DETAIL)
                elif get_settings().container_enabled:
                    raise RuntimeError("container manager is unavailable")
            await delete_workspace(db, workspace_id, tenant=tenant)
        except (WorkspaceNotFoundError, RepoNotFoundError):
            raise HTTPException(status_code=404, detail="Workspace not found")
        except WorkspaceHasDelegatedThreads:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "thread_children_present",
                    "message": "Workspace sessions parent delegated child threads",
                },
            )
        except HTTPException:
            raise
        except Exception:
            logger.error("Failed to delete workspace")
            raise HTTPException(status_code=500, detail="Failed to delete workspace")

